import sys
def top_words(path, n=10):
    counts = {}
    for line in open(path):
        for w in line.split():
            counts[w] = counts.get(w, 0) + 1
    return sorted(counts.items(), key=lambda kv: kv[1])[:n]
if __name__ == "__main__":
    for w, c in top_words(sys.argv[1], int(sys.argv[2])): print(w, c)
